flow.typescript:
// D1 · Part 1~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d01_flow.ts
//   환경 확인 → TTS(합성 신호) → 소리 보기 → ASR·RTF → CER → 음성 비서(STT → LLM → TTS)
//   OPENAI_API_KEY 있으면 Whisper API 받아쓰기, ANTHROPIC_API_KEY 있으면 Claude 답변 (없으면 건너뜀 · 규칙 기반)
//   실제 음성으로 해 보려면 WAV 경로를 붙여 실행: node --experimental-strip-types d01_flow.ts 내녹음.wav (없으면 합성 신호 · 흐름 확인용)
import { existsSync, readFileSync, writeFileSync } from "node:fs";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const SR = 16000; // 음성 모델 입력 표준: 16kHz mono

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0): Float32Array {
  // 말소리 비슷한 합성 신호(16kHz mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR; // 억양처럼 천천히 오르내림
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    const env = Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))); // 1초에 음절 5개쯤
    y[i] = v * env + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}

function writeWav(path: string, y: Float32Array, sr: number = SR): void {
  // 16-bit PCM mono WAV: 44바이트 머리말 + 샘플
  const buf = Buffer.alloc(44 + y.length * 2);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + y.length * 2, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(1, 20); // 1 = PCM
  buf.writeUInt16LE(1, 22); // 채널 1개 (mono)
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * 2, 28); // 1초 바이트 수
  buf.writeUInt16LE(2, 32); // 샘플 하나 바이트 수
  buf.writeUInt16LE(16, 34); // 16비트
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) {
    const v = Math.max(-1, Math.min(1, y[i])); // -1~1 밖은 잘라 냄
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { y: Float32Array; sr: number; channels: number } {
  // PCM 16비트 · float 32비트 WAV를 읽어 mono Float32Array로 (여러 채널이면 평균)
  const b = readFileSync(path);
  if (b.length < 12 || b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 0;
  let channels = 1;
  let sr = 0;
  let bits = 0;
  let pos = 12;
  while (pos + 8 <= b.length) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      channels = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const end = Math.min(b.length, body + size); // 크기가 잘못 적힌 파일도 있는 만큼만 읽음
      const step = (bits / 8) * channels;
      if (!((fmt === 1 && bits === 16) || (fmt === 3 && bits === 32))) throw new Error(`${path}: 16비트 PCM 또는 32비트 float만 읽어요`);
      const n = Math.floor((end - body) / step);
      const y = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        let s = 0;
        for (let c = 0; c < channels; c++) {
          const at = body + i * step + c * (bits / 8);
          s += fmt === 1 ? b.readInt16LE(at) / 32768 : b.readFloatLE(at);
        }
        y[i] = s / channels;
      }
      return { y, sr, channels };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}
const N_FFT = 512; // Python은 400, 이 FFT는 2의 거듭제곱이 필요해서 512 (창 길이는 400 = 25ms)
const WIN = 400;
const HOP = 160; // 10ms
const N_MELS = 80;

function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number): number[][] {
  // 삼각형 멜 필터 80개 (낮은 소리는 촘촘하게, 높은 소리는 성기게)
  const pts = Array.from({ length: N_MELS + 2 }, (_, i) => Math.floor(((N_FFT + 1) * mel2hz((hz2mel(sr / 2) * i) / (N_MELS + 1))) / sr));
  return Array.from({ length: N_MELS }, (_, m) => {
    const row = new Array<number>(N_FFT / 2 + 1).fill(0);
    for (let k = pts[m]; k < pts[m + 1]; k++) row[k] = (k - pts[m]) / Math.max(1, pts[m + 1] - pts[m]);
    for (let k = pts[m + 1]; k < pts[m + 2]; k++) row[k] = (pts[m + 2] - k) / Math.max(1, pts[m + 2] - pts[m + 1]);
    return row;
  });
}

function logMel(y: Float32Array, sr: number): number[][] {
  // 로그 멜 스펙트로그램 [시간 칸][멜 80] (dB, 가장 큰 값 = 0 dB)
  const bank = melBank(sr);
  const frames: number[][] = [];
  const re = new Float64Array(N_FFT);
  const im = new Float64Array(N_FFT);
  for (let s = 0; s + WIN <= y.length; s += HOP) {
    re.fill(0);
    im.fill(0);
    for (let i = 0; i < WIN; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / WIN)); // 한(Hann) 창
    fft(re, im);
    const pow = Array.from({ length: N_FFT / 2 + 1 }, (_, k) => re[k] * re[k] + im[k] * im[k]);
    frames.push(bank.map((row) => row.reduce((acc, w, k) => acc + w * pow[k], 0)));
  }
  const top = frames.reduce((m, f) => Math.max(m, ...f), 1e-10); // 가장 큰 값
  return frames.map((f) => f.map((v) => 10 * Math.log10(Math.max(v, 1e-10) / top)));
}
function writeBmp(path: string, img: number[][]): void {
  // img[x][y] (0~1) → 24비트 BMP 그림 파일 (아래가 낮은 소리, 어두운 파랑 → 청록 → 노랑)
  const w = img.length;
  const h = w ? img[0].length : 0;
  const rowBytes = Math.ceil((w * 3) / 4) * 4; // 한 줄은 4바이트 배수
  const buf = Buffer.alloc(54 + rowBytes * h);
  buf.write("BM", 0, "ascii");
  buf.writeUInt32LE(buf.length, 2);
  buf.writeUInt32LE(54, 10);
  buf.writeUInt32LE(40, 14);
  buf.writeInt32LE(w, 18);
  buf.writeInt32LE(h, 22); // 양수 = 아래 줄부터 저장
  buf.writeUInt16LE(1, 26);
  buf.writeUInt16LE(24, 28);
  buf.writeUInt32LE(rowBytes * h, 34);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const v = Math.max(0, Math.min(1, img[x][y]));
      const at = 54 + y * rowBytes + x * 3;
      buf[at] = Math.round(255 * (0.35 * (1 - v))); // B
      buf[at + 1] = Math.round(255 * Math.min(1, 0.1 + v)); // G
      buf[at + 2] = Math.round(255 * v * v); // R
    }
  }
  writeFileSync(path, buf);
}

function waveSvg(path: string, y: Float32Array, title: string): void {
  // 파형을 SVG 그림으로: 가로 칸마다 가장 작은·큰 값을 세로선으로
  const W = 1200;
  const H = 200;
  const per = Math.max(1, Math.floor(y.length / W));
  let d = "";
  for (let x = 0; x < W && x * per < y.length; x++) {
    let lo = 1;
    let hi = -1;
    for (let i = x * per; i < Math.min(y.length, (x + 1) * per); i++) {
      lo = Math.min(lo, y[i]);
      hi = Math.max(hi, y[i]);
    }
    d += `M${x} ${((1 - hi) * H) / 2}V${((1 - lo) * H) / 2}`;
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H + 24}"><text x="4" y="16" font-size="14">${title}</text><path transform="translate(0 24)" d="${d}" stroke="#1E9E8F" fill="none"/></svg>`;
  writeFileSync(path, svg);
}

function showAudio(path: string, title: string = ""): { y: Float32Array; sr: number } {
  // 파형(SVG) + 로그 멜 스펙트로그램(BMP)을 저장하고 샘플 배열과 샘플링 레이트를 돌려준다
  const { y, sr } = readWav(path);
  let lo = 0;
  let hi = 0;
  for (const v of y) {
    lo = Math.min(lo, v);
    hi = Math.max(hi, v);
  }
  console.log(`샘플 수: ${y.length.toLocaleString()} | 샘플링 레이트: ${sr} Hz | 길이: ${(y.length / sr).toFixed(2)}초 | 범위: [${lo.toFixed(3)}, ${hi.toFixed(3)}]`);
  const base = path.replace(/\.wav$/i, "");
  waveSvg(`${base}_wave.svg`, y, `Waveform ${title}`);
  const S = logMel(y, sr);
  writeBmp(`${base}_mel.bmp`, S.map((f) => f.map((db) => (db + 80) / 80))); // -80~0 dB → 0~1
  console.log(`그림 저장: ${base}_wave.svg, ${base}_mel.bmp (멜 ${N_MELS}개 × ${S.length}칸)`);
  return { y, sr };
}
function isRecord(v: unknown): v is Record<string, unknown> {
  // JSON 응답은 모양을 모르는 unknown → 객체인지 먼저 확인하고 꺼낸다
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
type Word = { word: string; start: number; end: number; speaker?: string };
type SttResult = { text: string; words: Word[]; duration: number; elapsed: number; engine: string };

async function transcribe(path: string, language: string = "ko"): Promise<SttResult> {
  // 받아쓰기: OPENAI_API_KEY가 있으면 Whisper API(단어 시각 포함), 없으면 인식은 건너뛰고 파이프라인만 진행
  const { y, sr } = readWav(path);
  const duration = y.length / sr;
  const t0 = performance.now();
  const key = process.env.OPENAI_API_KEY;
  if (!key) return { text: "", words: [], duration, elapsed: 0, engine: "인식 생략 (OPENAI_API_KEY 없음)" };
  try {
    const form = new FormData();
    form.append("file", new Blob([new Uint8Array(readFileSync(path))], { type: "audio/wav" }), "audio.wav");
    form.append("model", "whisper-1");
    form.append("language", language);
    form.append("response_format", "verbose_json");
    form.append("timestamp_granularities[]", "word");
    const res = await fetch("https://api.openai.com/v1/audio/transcriptions", { method: "POST", headers: { Authorization: `Bearer ${key}` }, body: form });
    if (!res.ok) throw new Error(`HTTP ${res.status}`); // 응답 본문은 로그에 남기지 않음
    const data: unknown = await res.json();
    const text = isRecord(data) && typeof data.text === "string" ? data.text.trim() : "";
    const raw = isRecord(data) && Array.isArray(data.words) ? data.words : [];
    const words: Word[] = raw.filter(isRecord).map((w) => ({ word: String(w.word ?? ""), start: Number(w.start ?? 0), end: Number(w.end ?? 0) }));
    return { text, words, duration, elapsed: (performance.now() - t0) / 1000, engine: "OpenAI whisper-1" };
  } catch (e) {
    console.log(`[주의] STT 호출 실패 → 인식 생략: ${String(e).slice(0, 120)}`);
    return { text: "", words: [], duration, elapsed: (performance.now() - t0) / 1000, engine: "인식 실패" };
  }
}
function speechSegments(y: Float32Array, sr: number = SR, topDb: number = 30): Array<[number, number]> {
  // 말소리 구간(초): 25ms 창·10ms 간격의 세기가 가장 큰 창보다 topDb 이상 작으면 쉼으로 본다
  const win = Math.round(0.025 * sr);
  const hop = Math.round(0.01 * sr);
  const db: number[] = [];
  for (let s = 0; s + win <= y.length; s += hop) {
    let e = 0;
    for (let i = s; i < s + win; i++) e += y[i] * y[i];
    db.push(10 * Math.log10(e / win + 1e-12));
  }
  const top = db.length ? Math.max(...db) : 0;
  const segs: Array<[number, number]> = [];
  db.forEach((v, k) => {
    const t0 = (k * hop) / sr;
    const t1 = (k * hop + win) / sr;
    if (v < top - topDb) return;
    const last = segs[segs.length - 1];
    if (last && t0 - last[1] < 0.3) last[1] = t1; // 0.3초보다 짧은 쉼은 이어 붙임
    else segs.push([t0, t1]);
  });
  return segs.filter(([a, b]) => b - a > 0.3);
}
function rtf(elapsed: number, duration: number): number {
  // 실시간 비율(RTF) = 처리 시간 ÷ 오디오 길이 (1보다 작으면 실시간보다 빠름)
  return duration > 0 ? elapsed / duration : 0;
}
function tts(text: string, outWav: string, voice: string = "ko-KR-SunHiNeural", rate: string = "+0%"): string {
  // 글자 → 소리 자리: Node 내장만으로는 진짜 음성 합성을 못 해서, 문장 길이·말 빠르기·목소리에 맞춘 합성 신호를 16kHz WAV로 쓴다
  // (Python 버전은 edge-tts로 실제 목소리를 만든다. 실제 음성이 필요하면 TTS 서비스를 붙이는 자리)
  const speed = 1 + Number.parseFloat(rate) / 100; // "+30%" → 1.3배 빠르게
  const f0 = /InJoon|Hyunsu/.test(voice) ? 110 : 210; // 남성 목소리는 낮게
  const seconds = Math.max(1, (text.length * 0.12) / (speed > 0 ? speed : 1));
  writeWav(outWav, synthVoice(seconds, f0), SR);
  return outWav;
}
function resample(y: Float32Array, from: number, to: number = SR): Float32Array {
  // 선형 보간으로 샘플링 레이트 바꾸기 (예: 48000 → 16000)
  if (from === to) return y;
  const out = new Float32Array(Math.floor((y.length * to) / from));
  for (let i = 0; i < out.length; i++) {
    const x = (i * from) / to;
    const k = Math.floor(x);
    const a = y[k] ?? 0;
    const b = y[k + 1] ?? a;
    out[i] = a + (b - a) * (x - k);
  }
  return out;
}
function userWav(fallback: () => string, out: string = "input.wav"): string {
  // 입력 음성: 실행할 때 WAV 경로를 주면(예: node x.ts 내녹음.wav) 16kHz mono로 바꿔 쓰고, 없으면 합성 신호
  // 합성 신호는 말이 아니므로, API 키와 실제 음성이 없으면 이 코드는 '흐름 확인용'으로만 돈다
  const src = process.argv.slice(2).find((a) => !a.startsWith("--"));
  if (src && existsSync(src)) {
    const { y, sr } = readWav(src);
    writeWav(out, resample(y, sr), SR);
    console.log(`입력: ${src} → ${out} (16kHz mono)`);
    return out;
  }
  console.log("입력: 합성 신호 (실제 음성 WAV 경로를 주면 그 파일로) · 키 · 실제 음성이 없으면 흐름 확인용");
  return fallback();
}
function editCount<T>(r: T[], h: T[]): number {
  // 편집 거리(최소 고침 횟수): 한 줄씩만 들고 계산
  let prev = Array.from({ length: h.length + 1 }, (_, j) => j);
  for (let i = 1; i <= r.length; i++) {
    const cur = [i];
    for (let j = 1; j <= h.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (r[i - 1] === h[j - 1] ? 0 : 1)));
    prev = cur;
  }
  return prev[h.length];
}

function cer(ref: string | string[], hyp: string | string[]): number {
  // 글자 오류율 (jiwer.cer와 같은 방식: 앞뒤 공백 정리, 공백도 한 글자, 여러 문장은 합쳐서 계산)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rc = [...r.trim()];
    edits += editCount(rc, [...(H[i] ?? "").trim()]);
    total += rc.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
function normalizeKo(s: string): string {
  return s
    .replace(/[^\p{L}\p{N}_\s]/gu, "") // 문장부호 제거
    .replace(/\s+/g, ""); // 공백 제거 (띄어쓰기 영향 배제)
}

function cerKo(ref: string, hyp: string): number {
  // 정규화한 뒤 글자 오류율. 정답이 비면 계산할 수 없으므로 0
  const r = normalizeKo(ref);
  return r ? cer(r, normalizeKo(hyp)) : 0;
}
async function callClaude(system: string, user: string, model: string, maxTokens: number): Promise<string> {
  // Anthropic Messages API를 fetch로 직접 호출 (키는 환경 변수에서만 읽는다)
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error("ANTHROPIC_API_KEY 없음");
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
    body: JSON.stringify({ model, max_tokens: maxTokens, system, messages: [{ role: "user", content: user }] }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`); // 응답 본문은 로그에 남기지 않음
  const data: unknown = await res.json();
  const blocks = isRecord(data) && Array.isArray(data.content) ? data.content : [];
  return blocks.filter(isRecord).filter((b) => b.type === "text" && typeof b.text === "string").map((b) => String(b.text)).join("");
}
const LLM_MODEL = "claude-haiku-5-5"; // 빠른 응답용 경량 모델
const SYSTEM_PROMPT =
  "당신은 친절한 한국어 음성 비서입니다. 답변은 TTS로 읽히므로 " +
  "마크다운, 목록, 이모지, 괄호를 쓰지 말고 1~2문장의 짧은 구어체로 답하세요.";

function ruleBasedReply(text: string): string {
  // API 키가 없을 때 쓰는 규칙 기반 답변
  const kst = new Date(Date.now() + 9 * 3600 * 1000); // UTC+9 (한국 시간)
  if (text.includes("시") && (text.includes("몇") || text.includes("시간"))) return `지금은 ${kst.getUTCHours()}시 ${kst.getUTCMinutes()}분입니다.`;
  if (text.includes("이름")) return "저는 음성 AI 과정 실습용 비서입니다.";
  if (text.includes("날씨")) return "저는 아직 날씨 정보를 조회할 수 없어요. 5주차에 도구 연결을 배우면 가능해집니다.";
  if (!text.trim()) return "잘 듣지 못했어요. 한 번 더 말씀해 주세요.";
  return `'${text}'라고 말씀하셨네요. 잘 들었습니다.`;
}

async function llmReply(userText: string): Promise<[string, number]> {
  // ANTHROPIC_API_KEY가 있으면 Claude, 없거나 실패하면 규칙 기반 → [답변, 걸린 시간 초]
  const t0 = performance.now();
  let reply = "";
  if (process.env.ANTHROPIC_API_KEY) {
    try {
      reply = await callClaude(SYSTEM_PROMPT, userText || "안녕하세요", LLM_MODEL, 200);
    } catch (e) {
      console.log(`[주의] Claude 호출 실패 → 규칙 기반: ${String(e).slice(0, 120)}`);
    }
  }
  return [reply || ruleBasedReply(userText), (performance.now() - t0) / 1000];
}
async function voiceAgent(inputWav: string): Promise<Record<string, number>> {
  // 듣기(STT) → 생각하기(LLM) → 말하기(TTS)를 한 번 돌리고 단계별 지연 시간을 그린다
  const timings: Record<string, number> = {};
  const heard = await transcribe(inputWav); // 1) STT
  timings.STT = heard.elapsed;
  console.log(`사용자: ${heard.text || "(인식된 말 없음)"}  [${heard.engine}]`);
  const [reply, llmSec] = await llmReply(heard.text); // 2) LLM
  timings.LLM = llmSec;
  console.log(`비서  : ${reply}`);
  const t0 = performance.now();
  const out = tts(reply, "agent_reply.wav"); // 3) TTS
  timings.TTS = (performance.now() - t0) / 1000;
  console.log("답변 음성:", out);

  let total = 0;
  for (const [k, v] of Object.entries(timings)) {
    console.log(`  ${k.padEnd(4)}: ${(v * 1000).toFixed(0).padStart(7)} ms`);
    total += v;
  }
  console.log(`  합계: ${(total * 1000).toFixed(0).padStart(7)} ms`);

  // 지연 시간 막대 (SVG): 1초 목표선과 함께
  const colors: Record<string, string> = { STT: "#1E9E8F", LLM: "#E8A33D", TTS: "#C2417A" };
  const scale = 600 / Math.max(1000, total * 1000);
  let x = 0;
  const bars = Object.entries(timings).map(([k, v]) => {
    const w = v * 1000 * scale;
    const r = `<rect x="${x}" y="10" width="${w}" height="30" fill="${colors[k]}"><title>${k} ${(v * 1000).toFixed(0)} ms</title></rect>`;
    x += w;
    return r;
  });
  writeFileSync("agent_latency.svg", `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 620 60">${bars.join("")}<line x1="${1000 * scale}" x2="${1000 * scale}" y1="0" y2="50" stroke="gray" stroke-dasharray="4"/><text x="${1000 * scale + 4}" y="56" font-size="10" fill="gray">1s target</text></svg>`);
  console.log("그림 저장: agent_latency.svg");
  return timings;
}
// Part 1 · 환경 확인
console.log(`Node ${process.version} | fetch ${typeof fetch === "function" ? "있음" : "없음"} | 받아쓰기 ${process.env.OPENAI_API_KEY ? "Whisper API" : "건너뜀"} | 답변 ${process.env.ANTHROPIC_API_KEY ? "Claude" : "규칙 기반"}`);

// Part 2 · TTS: 글자 → 소리
const sampleText = "안녕하세요. 음성 AI 전문가 과정에 오신 것을 환영합니다.";
const wav = userWav(() => tts(sampleText, "sample.wav")); // 이 문장을 읽은 녹음을 주면 실제 인식 · CER

// Part 3 · 소리 눈으로 보기
const { y, sr } = showAudio(wav, "(TTS sample)");
const head = readFileSync(wav);
check(Math.abs(y.length / sr - head.readUInt32LE(40) / head.readUInt32LE(28)) < 1e-3, "길이(초) = 샘플 수 ÷ 샘플링 레이트(16,000) 입니다.");

// Part 5 · ASR 받아쓰기와 RTF, CER
const heard = await transcribe(wav);
console.log(`인식: ${heard.text || "(없음)"} [${heard.engine}] | 말소리 구간 ${speechSegments(y).length}개 | RTF ${rtf(heard.elapsed, heard.duration).toFixed(3)} | CER ${(cerKo(sampleText, heard.text) * 100).toFixed(2)}%`);
check(Math.abs(cer("오늘날씨좋다", "오날시좋다요") - 0.5) < 1e-9, "cer(정답, 결과)");

// Part 6 · 미니 음성 비서
const qWav = tts("음성 인식과 음성 합성의 차이를 짧게 설명해 줘.", "question.wav", "ko-KR-InJoonNeural");
const timings = await voiceAgent(qWav);
check(["STT", "LLM", "TTS"].every((k) => k in timings), "STT → LLM → TTS 세 단계를 모두 재야 합니다.");

tech.typescript:
// D1 · Part 2 · TTS + Part 5 · ASR — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d01_tech.ts   (글자 → 소리(TTS 자리) → 다시 글자(ASR) → CER로 비교)
// 받아쓰기 분기: OPENAI_API_KEY가 있으면 Whisper API로 실제 인식, 없으면 인식은 건너뛰어요.
//   실제 음성으로 해 보려면 WAV 경로를 붙여 실행: node --experimental-strip-types d01_tech.ts 내녹음.wav (없으면 합성 신호 · 흐름 확인용)
import { existsSync, readFileSync, writeFileSync } from "node:fs";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const SR = 16000; // 음성 모델 입력 표준: 16kHz mono

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0): Float32Array {
  // 말소리 비슷한 합성 신호(16kHz mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR; // 억양처럼 천천히 오르내림
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    const env = Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))); // 1초에 음절 5개쯤
    y[i] = v * env + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}

function writeWav(path: string, y: Float32Array, sr: number = SR): void {
  // 16-bit PCM mono WAV: 44바이트 머리말 + 샘플
  const buf = Buffer.alloc(44 + y.length * 2);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + y.length * 2, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(1, 20); // 1 = PCM
  buf.writeUInt16LE(1, 22); // 채널 1개 (mono)
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * 2, 28); // 1초 바이트 수
  buf.writeUInt16LE(2, 32); // 샘플 하나 바이트 수
  buf.writeUInt16LE(16, 34); // 16비트
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) {
    const v = Math.max(-1, Math.min(1, y[i])); // -1~1 밖은 잘라 냄
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { y: Float32Array; sr: number; channels: number } {
  // PCM 16비트 · float 32비트 WAV를 읽어 mono Float32Array로 (여러 채널이면 평균)
  const b = readFileSync(path);
  if (b.length < 12 || b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 0;
  let channels = 1;
  let sr = 0;
  let bits = 0;
  let pos = 12;
  while (pos + 8 <= b.length) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      channels = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const end = Math.min(b.length, body + size); // 크기가 잘못 적힌 파일도 있는 만큼만 읽음
      const step = (bits / 8) * channels;
      if (!((fmt === 1 && bits === 16) || (fmt === 3 && bits === 32))) throw new Error(`${path}: 16비트 PCM 또는 32비트 float만 읽어요`);
      const n = Math.floor((end - body) / step);
      const y = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        let s = 0;
        for (let c = 0; c < channels; c++) {
          const at = body + i * step + c * (bits / 8);
          s += fmt === 1 ? b.readInt16LE(at) / 32768 : b.readFloatLE(at);
        }
        y[i] = s / channels;
      }
      return { y, sr, channels };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}
function isRecord(v: unknown): v is Record<string, unknown> {
  // JSON 응답은 모양을 모르는 unknown → 객체인지 먼저 확인하고 꺼낸다
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
type Word = { word: string; start: number; end: number; speaker?: string };
type SttResult = { text: string; words: Word[]; duration: number; elapsed: number; engine: string };

async function transcribe(path: string, language: string = "ko"): Promise<SttResult> {
  // 받아쓰기: OPENAI_API_KEY가 있으면 Whisper API(단어 시각 포함), 없으면 인식은 건너뛰고 파이프라인만 진행
  const { y, sr } = readWav(path);
  const duration = y.length / sr;
  const t0 = performance.now();
  const key = process.env.OPENAI_API_KEY;
  if (!key) return { text: "", words: [], duration, elapsed: 0, engine: "인식 생략 (OPENAI_API_KEY 없음)" };
  try {
    const form = new FormData();
    form.append("file", new Blob([new Uint8Array(readFileSync(path))], { type: "audio/wav" }), "audio.wav");
    form.append("model", "whisper-1");
    form.append("language", language);
    form.append("response_format", "verbose_json");
    form.append("timestamp_granularities[]", "word");
    const res = await fetch("https://api.openai.com/v1/audio/transcriptions", { method: "POST", headers: { Authorization: `Bearer ${key}` }, body: form });
    if (!res.ok) throw new Error(`HTTP ${res.status}`); // 응답 본문은 로그에 남기지 않음
    const data: unknown = await res.json();
    const text = isRecord(data) && typeof data.text === "string" ? data.text.trim() : "";
    const raw = isRecord(data) && Array.isArray(data.words) ? data.words : [];
    const words: Word[] = raw.filter(isRecord).map((w) => ({ word: String(w.word ?? ""), start: Number(w.start ?? 0), end: Number(w.end ?? 0) }));
    return { text, words, duration, elapsed: (performance.now() - t0) / 1000, engine: "OpenAI whisper-1" };
  } catch (e) {
    console.log(`[주의] STT 호출 실패 → 인식 생략: ${String(e).slice(0, 120)}`);
    return { text: "", words: [], duration, elapsed: (performance.now() - t0) / 1000, engine: "인식 실패" };
  }
}
function rtf(elapsed: number, duration: number): number {
  // 실시간 비율(RTF) = 처리 시간 ÷ 오디오 길이 (1보다 작으면 실시간보다 빠름)
  return duration > 0 ? elapsed / duration : 0;
}
function tts(text: string, outWav: string, voice: string = "ko-KR-SunHiNeural", rate: string = "+0%"): string {
  // 글자 → 소리 자리: Node 내장만으로는 진짜 음성 합성을 못 해서, 문장 길이·말 빠르기·목소리에 맞춘 합성 신호를 16kHz WAV로 쓴다
  // (Python 버전은 edge-tts로 실제 목소리를 만든다. 실제 음성이 필요하면 TTS 서비스를 붙이는 자리)
  const speed = 1 + Number.parseFloat(rate) / 100; // "+30%" → 1.3배 빠르게
  const f0 = /InJoon|Hyunsu/.test(voice) ? 110 : 210; // 남성 목소리는 낮게
  const seconds = Math.max(1, (text.length * 0.12) / (speed > 0 ? speed : 1));
  writeWav(outWav, synthVoice(seconds, f0), SR);
  return outWav;
}
function resample(y: Float32Array, from: number, to: number = SR): Float32Array {
  // 선형 보간으로 샘플링 레이트 바꾸기 (예: 48000 → 16000)
  if (from === to) return y;
  const out = new Float32Array(Math.floor((y.length * to) / from));
  for (let i = 0; i < out.length; i++) {
    const x = (i * from) / to;
    const k = Math.floor(x);
    const a = y[k] ?? 0;
    const b = y[k + 1] ?? a;
    out[i] = a + (b - a) * (x - k);
  }
  return out;
}
function userWav(fallback: () => string, out: string = "input.wav"): string {
  // 입력 음성: 실행할 때 WAV 경로를 주면(예: node x.ts 내녹음.wav) 16kHz mono로 바꿔 쓰고, 없으면 합성 신호
  // 합성 신호는 말이 아니므로, API 키와 실제 음성이 없으면 이 코드는 '흐름 확인용'으로만 돈다
  const src = process.argv.slice(2).find((a) => !a.startsWith("--"));
  if (src && existsSync(src)) {
    const { y, sr } = readWav(src);
    writeWav(out, resample(y, sr), SR);
    console.log(`입력: ${src} → ${out} (16kHz mono)`);
    return out;
  }
  console.log("입력: 합성 신호 (실제 음성 WAV 경로를 주면 그 파일로) · 키 · 실제 음성이 없으면 흐름 확인용");
  return fallback();
}
function editCount<T>(r: T[], h: T[]): number {
  // 편집 거리(최소 고침 횟수): 한 줄씩만 들고 계산
  let prev = Array.from({ length: h.length + 1 }, (_, j) => j);
  for (let i = 1; i <= r.length; i++) {
    const cur = [i];
    for (let j = 1; j <= h.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (r[i - 1] === h[j - 1] ? 0 : 1)));
    prev = cur;
  }
  return prev[h.length];
}

function cer(ref: string | string[], hyp: string | string[]): number {
  // 글자 오류율 (jiwer.cer와 같은 방식: 앞뒤 공백 정리, 공백도 한 글자, 여러 문장은 합쳐서 계산)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rc = [...r.trim()];
    edits += editCount(rc, [...(H[i] ?? "").trim()]);
    total += rc.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
function normalizeKo(s: string): string {
  return s
    .replace(/[^\p{L}\p{N}_\s]/gu, "") // 문장부호 제거
    .replace(/\s+/g, ""); // 공백 제거 (띄어쓰기 영향 배제)
}

function cerKo(ref: string, hyp: string): number {
  // 정규화한 뒤 글자 오류율. 정답이 비면 계산할 수 없으므로 0
  const r = normalizeKo(ref);
  return r ? cer(r, normalizeKo(hyp)) : 0;
}
const sampleText = "안녕하세요. 음성 AI 전문가 과정에 오신 것을 환영합니다.";
const wav = userWav(() => tts(sampleText, "sample.wav")); // 글자 → 소리 (이 문장을 읽은 녹음을 줘도 됨)
const { y, sr } = readWav(wav);
console.log(`TTS: ${wav} | ${sr} Hz · ${(y.length / sr).toFixed(2)}초`);

const r = await transcribe(wav); // 소리 → 글자
for (const w of r.words) console.log(`  [${w.start.toFixed(2).padStart(6)}s → ${w.end.toFixed(2).padStart(6)}s] ${w.word}`);
console.log(`ASR: ${r.text || "(없음)"} [${r.engine}] | RTF ${rtf(r.elapsed, r.duration).toFixed(3)}`);

const c = cerKo(sampleText, r.text);
console.log(`CER: ${(c * 100).toFixed(2)}%`);
const head = readFileSync(wav);
check(sr === 16000 && Math.abs(y.length / sr - head.readUInt32LE(40) / head.readUInt32LE(28)) < 1e-3, "음성 모델 입력 표준은 16kHz mono, 길이 = 샘플 수 ÷ 16000 입니다.");

stack.typescript:
// D1 · Part 1 · 개발환경 확인 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d01_stack.ts
import { spawnSync } from "node:child_process";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
