// D1 · Part 3 · 소리 눈으로 보기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d01_sampling.ts
//   파형 SVG · 로그 멜 스펙트로그램 BMP 저장 → 묵음 구간과 VAD(에너지 기반) → 8kHz와 16kHz 비교
import { readFileSync, writeFileSync } from "node:fs";

