// D1 · Part 5 · ASR 받아쓰기와 RTF — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d01_asr.ts
// 받아쓰기 분기: OPENAI_API_KEY가 있으면 Whisper API로 실제 인식, 없으면 말소리 구간만 찾고 인식은 건너뛰어요.
//   실제 음성으로 해 보려면 WAV 경로를 붙여 실행: node --experimental-strip-types d01_asr.ts 내녹음.wav (없으면 합성 신호 · 흐름 확인용)
import { existsSync, readFileSync, writeFileSync } from "node:fs";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const SR = 16000; // 음성 모델 입력 표준: 16kHz mono

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0): Float32Array {
  // 말소리 비슷한 합성 신호(16kHz mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR; // 억양처럼 천천히 오르내림
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    const env = Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))); // 1초에 음절 5개쯤
    y[i] = v * env + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}

function writeWav(path: string, y: Float32Array, sr: number = SR): void {
  // 16-bit PCM mono WAV: 44바이트 머리말 + 샘플
  const buf = Buffer.alloc(44 + y.length * 2);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + y.length * 2, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(1, 20); // 1 = PCM
  buf.writeUInt16LE(1, 22); // 채널 1개 (mono)
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * 2, 28); // 1초 바이트 수
  buf.writeUInt16LE(2, 32); // 샘플 하나 바이트 수
  buf.writeUInt16LE(16, 34); // 16비트
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) {
    const v = Math.max(-1, Math.min(1, y[i])); // -1~1 밖은 잘라 냄
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { y: Float32Array; sr: number; channels: number } {
  // PCM 16비트 · float 32비트 WAV를 읽어 mono Float32Array로 (여러 채널이면 평균)
  const b = readFileSync(path);
  if (b.length < 12 || b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 0;
  let channels = 1;
  let sr = 0;
  let bits = 0;
  let pos = 12;
  while (pos + 8 <= b.length) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      channels = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const end = Math.min(b.length, body + size); // 크기가 잘못 적힌 파일도 있는 만큼만 읽음
      const step = (bits / 8) * channels;
      if (!((fmt === 1 && bits === 16) || (fmt === 3 && bits === 32))) throw new Error(`${path}: 16비트 PCM 또는 32비트 float만 읽어요`);
      const n = Math.floor((end - body) / step);
      const y = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        let s = 0;
        for (let c = 0; c < channels; c++) {
          const at = body + i * step + c * (bits / 8);
          s += fmt === 1 ? b.readInt16LE(at) / 32768 : b.readFloatLE(at);
        }
        y[i] = s / channels;
      }
      return { y, sr, channels };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}
function isRecord(v: unknown): v is Record<string, unknown> {
  // JSON 응답은 모양을 모르는 unknown → 객체인지 먼저 확인하고 꺼낸다
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
type Word = { word: string; start: number; end: number; speaker?: string };
type SttResult = { text: string; words: Word[]; duration: number; elapsed: number; engine: string };

async function transcribe(path: string, language: string = "ko"): Promise<SttResult> {
  // 받아쓰기: OPENAI_API_KEY가 있으면 Whisper API(단어 시각 포함), 없으면 인식은 건너뛰고 파이프라인만 진행
  const { y, sr } = readWav(path);
  const duration = y.length / sr;
  const t0 = performance.now();
  const key = process.env.OPENAI_API_KEY;
  if (!key) return { text: "", words: [], duration, elapsed: 0, engine: "인식 생략 (OPENAI_API_KEY 없음)" };
  try {
    const form = new FormData();
    form.append("file", new Blob([new Uint8Array(readFileSync(path))], { type: "audio/wav" }), "audio.wav");
    form.append("model", "whisper-1");
    form.append("language", language);
    form.append("response_format", "verbose_json");
    form.append("timestamp_granularities[]", "word");
    const res = await fetch("https://api.openai.com/v1/audio/transcriptions", { method: "POST", headers: { Authorization: `Bearer ${key}` }, body: form });
    if (!res.ok) throw new Error(`HTTP ${res.status}`); // 응답 본문은 로그에 남기지 않음
    const data: unknown = await res.json();
    const text = isRecord(data) && typeof data.text === "string" ? data.text.trim() : "";
    const raw = isRecord(data) && Array.isArray(data.words) ? data.words : [];
    const words: Word[] = raw.filter(isRecord).map((w) => ({ word: String(w.word ?? ""), start: Number(w.start ?? 0), end: Number(w.end ?? 0) }));
    return { text, words, duration, elapsed: (performance.now() - t0) / 1000, engine: "OpenAI whisper-1" };
  } catch (e) {
    console.log(`[주의] STT 호출 실패 → 인식 생략: ${String(e).slice(0, 120)}`);
    return { text: "", words: [], duration, elapsed: (performance.now() - t0) / 1000, engine: "인식 실패" };
  }
}
function speechSegments(y: Float32Array, sr: number = SR, topDb: number = 30): Array<[number, number]> {
  // 말소리 구간(초): 25ms 창·10ms 간격의 세기가 가장 큰 창보다 topDb 이상 작으면 쉼으로 본다
  const win = Math.round(0.025 * sr);
  const hop = Math.round(0.01 * sr);
  const db: number[] = [];
  for (let s = 0; s + win <= y.length; s += hop) {
    let e = 0;
    for (let i = s; i < s + win; i++) e += y[i] * y[i];
    db.push(10 * Math.log10(e / win + 1e-12));
  }
  const top = db.length ? Math.max(...db) : 0;
  const segs: Array<[number, number]> = [];
  db.forEach((v, k) => {
    const t0 = (k * hop) / sr;
    const t1 = (k * hop + win) / sr;
    if (v < top - topDb) return;
    const last = segs[segs.length - 1];
    if (last && t0 - last[1] < 0.3) last[1] = t1; // 0.3초보다 짧은 쉼은 이어 붙임
    else segs.push([t0, t1]);
  });
  return segs.filter(([a, b]) => b - a > 0.3);
}
function rtf(elapsed: number, duration: number): number {
  // 실시간 비율(RTF) = 처리 시간 ÷ 오디오 길이 (1보다 작으면 실시간보다 빠름)
  return duration > 0 ? elapsed / duration : 0;
}
function tts(text: string, outWav: string, voice: string = "ko-KR-SunHiNeural", rate: string = "+0%"): string {
  // 글자 → 소리 자리: Node 내장만으로는 진짜 음성 합성을 못 해서, 문장 길이·말 빠르기·목소리에 맞춘 합성 신호를 16kHz WAV로 쓴다
  // (Python 버전은 edge-tts로 실제 목소리를 만든다. 실제 음성이 필요하면 TTS 서비스를 붙이는 자리)
  const speed = 1 + Number.parseFloat(rate) / 100; // "+30%" → 1.3배 빠르게
  const f0 = /InJoon|Hyunsu/.test(voice) ? 110 : 210; // 남성 목소리는 낮게
  const seconds = Math.max(1, (text.length * 0.12) / (speed > 0 ? speed : 1));
  writeWav(outWav, synthVoice(seconds, f0), SR);
  return outWav;
}
function resample(y: Float32Array, from: number, to: number = SR): Float32Array {
  // 선형 보간으로 샘플링 레이트 바꾸기 (예: 48000 → 16000)
  if (from === to) return y;
  const out = new Float32Array(Math.floor((y.length * to) / from));
  for (let i = 0; i < out.length; i++) {
    const x = (i * from) / to;
    const k = Math.floor(x);
    const a = y[k] ?? 0;
    const b = y[k + 1] ?? a;
    out[i] = a + (b - a) * (x - k);
  }
  return out;
}
function userWav(fallback: () => string, out: string = "input.wav"): string {
  // 입력 음성: 실행할 때 WAV 경로를 주면(예: node x.ts 내녹음.wav) 16kHz mono로 바꿔 쓰고, 없으면 합성 신호
  // 합성 신호는 말이 아니므로, API 키와 실제 음성이 없으면 이 코드는 '흐름 확인용'으로만 돈다
  const src = process.argv.slice(2).find((a) => !a.startsWith("--"));
  if (src && existsSync(src)) {
    const { y, sr } = readWav(src);
    writeWav(out, resample(y, sr), SR);
    console.log(`입력: ${src} → ${out} (16kHz mono)`);
    return out;
  }
  console.log("입력: 합성 신호 (실제 음성 WAV 경로를 주면 그 파일로) · 키 · 실제 음성이 없으면 흐름 확인용");
  return fallback();
}
const sample = tts("안녕하세요. 음성 AI 전문가 과정에 오신 것을 환영합니다.", "sample.wav");
const myWav = userWav(() => tts("오늘부터 음성 AI를 배웁니다.", "my_voice.wav", "ko-KR-InJoonNeural"));

for (const path of [sample, myWav]) {
  const r = await transcribe(path);
  console.log(`\n${path}  [${r.engine}]`);
  for (const [a, b] of speechSegments(readWav(path).y)) console.log(`  말소리 구간 [${a.toFixed(2).padStart(6)}s → ${b.toFixed(2).padStart(6)}s]`);
  for (const w of r.words) console.log(`  [${w.start.toFixed(2).padStart(6)}s → ${w.end.toFixed(2).padStart(6)}s] ${w.word}`);
  console.log(`  처리 ${r.elapsed.toFixed(2)}s | 오디오 ${r.duration.toFixed(2)}s | RTF ${rtf(r.elapsed, r.duration).toFixed(3)}`);
}

const r = await transcribe(myWav);
console.log(`\n인식 결과: ${r.text || "(없음)"}`);
console.log(`${r.duration.toFixed(1)}초 음성을 ${r.elapsed.toFixed(2)}초 만에 처리 (RTF ${rtf(r.elapsed, r.duration).toFixed(2)})`);
const head = readFileSync(myWav);
check(Math.abs(r.duration - head.readUInt32LE(40) / head.readUInt32LE(28)) < 0.05, "받아쓰기가 잰 길이와 WAV 머리말의 길이(데이터 바이트 ÷ 1초 바이트)가 같아야 합니다.");

