  const t0 = performance.now();
  let reply = "";
  if (process.env.ANTHROPIC_API_KEY) {
    try {
      reply = await callClaude(SYSTEM_PROMPT, userText || "안녕하세요", LLM_MODEL, 200);
    } catch (e) {
      console.log(`[주의] Claude 호출 실패 → 규칙 기반: ${String(e).slice(0, 120)}`);
    }
  }
  return [reply || ruleBasedReply(userText), (performance.now() - t0) / 1000];
}
async function voiceAgent(inputWav: string): Promise<Record<string, number>> {
  // 듣기(STT) → 생각하기(LLM) → 말하기(TTS)를 한 번 돌리고 단계별 지연 시간을 그린다
  const timings: Record<string, number> = {};
  const heard = await transcribe(inputWav); // 1) STT
  timings.STT = heard.elapsed;
  console.log(`사용자: ${heard.text || "(인식된 말 없음)"}  [${heard.engine}]`);
  const [reply, llmSec] = await llmReply(heard.text); // 2) LLM
  timings.LLM = llmSec;
  console.log(`비서  : ${reply}`);
  const t0 = performance.now();
  const out = tts(reply, "agent_reply.wav"); // 3) TTS
  timings.TTS = (performance.now() - t0) / 1000;
  console.log("답변 음성:", out);

  let total = 0;
  for (const [k, v] of Object.entries(timings)) {
    console.log(`  ${k.padEnd(4)}: ${(v * 1000).toFixed(0).padStart(7)} ms`);
    total += v;
  }
  console.log(`  합계: ${(total * 1000).toFixed(0).padStart(7)} ms`);

  // 지연 시간 막대 (SVG): 1초 목표선과 함께
  const colors: Record<string, string> = { STT: "#1E9E8F", LLM: "#E8A33D", TTS: "#C2417A" };
  const scale = 600 / Math.max(1000, total * 1000);
  let x = 0;
  const bars = Object.entries(timings).map(([k, v]) => {
    const w = v * 1000 * scale;
    const r = `<rect x="${x}" y="10" width="${w}" height="30" fill="${colors[k]}"><title>${k} ${(v * 1000).toFixed(0)} ms</title></rect>`;
    x += w;
    return r;
  });
  writeFileSync("agent_latency.svg", `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 620 60">${bars.join("")}<line x1="${1000 * scale}" x2="${1000 * scale}" y1="0" y2="50" stroke="gray" stroke-dasharray="4"/><text x="${1000 * scale + 4}" y="56" font-size="10" fill="gray">1s target</text></svg>`);
  console.log("그림 저장: agent_latency.svg");
  return timings;
}
async function myAgent(inputWav: string): Promise<[string, string, string]> {
  const userText = (await transcribe(inputWav)).text; // ① 듣기: 음성 → 글자
  const [reply] = await llmReply(userText); // ② 생각하기: 글자 → 답변
  const out = tts(reply, "my_agent.wav"); // ③ 말하기: 답변 → 음성
  return [userText, reply, out];
}

